/// <summary>
/// UPSPricingAttribute of table <c>WarrantyInventTable</c> field ItemId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWarrantyInventTableItemId extends UPSPricingAttributeWarrantyInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WarrantyInventTable, ItemId);
}

public Set getAllowedValues()
{   
    var                 ret = new Set(Types::String);
    WarrantyInventTable warrantyInventTable;

    while select ItemId from warrantyInventTable
    {
        if (!ret.in(warrantyInventTable.ItemId))
        {
            ret.add(warrantyInventTable.ItemId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WarrantyInventTable, ItemId));
    qbr.value(queryValue(_value));
}
